<?php include "db.php";if(!isset($_SESSION['user_id'])||$_SESSION['role']!=='admin'){die("Admin access only. Please <a href='login.php'>log in</a> using an admin account.");}$msg="";if(isset($_POST['add_bus'])){$name=trim($_POST['bus_name']);$category=$_POST['category'];$source=trim($_POST['source']);$destination=trim($_POST['destination']);$date=$_POST['travel_date'];$time=$_POST['departure_time'];$seats=(int)$_POST['total_seats'];$price=(float)$_POST['price'];$stmt=mysqli_prepare($conn,"INSERT INTO buses(bus_name,category,source,destination,travel_date,departure_time,total_seats,available_seats,price) VALUES(?,?,?,?,?,?,?,?,?)");mysqli_stmt_bind_param($stmt,"ssssssiid",$name,$category,$source,$destination,$date,$time,$seats,$seats,$price);if(mysqli_stmt_execute($stmt))$msg="Bus added successfully.";else$msg="Unable to add bus: ".mysqli_error($conn);}if(isset($_POST['cancel_booking'])){$id=(int)$_POST['booking_id'];$stmt=mysqli_prepare($conn,"UPDATE bookings SET status='Cancelled' WHERE id=?");mysqli_stmt_bind_param($stmt,"i",$id);mysqli_stmt_execute($stmt);$msg="Booking cancelled.";} $buses=mysqli_query($conn,"SELECT * FROM buses ORDER BY travel_date,departure_time");$bookings=mysqli_query($conn,"SELECT bookings.*,users.name,buses.bus_name,buses.source,buses.destination FROM bookings JOIN users ON bookings.user_id=users.id JOIN buses ON bookings.bus_id=buses.id ORDER BY bookings.id DESC");?>
<!DOCTYPE html><html><head><title>GoBus Admin</title><link rel="stylesheet" href="style.css"></head><body><header><h1>GoBus Admin</h1><nav><a href="index.php">Home</a><a href="dashboard.php">Dashboard</a><a href="logout.php">Logout</a></nav></header><div class="container"><h2>Admin Panel</h2><?php if($msg)echo '<p class="message">'.htmlspecialchars($msg).'</p>';?><div class="form-box"><h3>Add Bus / Schedule</h3><form method="post"><label>Bus name</label><input name="bus_name" required><label>Category</label><select name="category"><option>Volvo AC</option><option>Sleeper Coach</option><option>Seater Coach</option></select><label>From</label><input name="source" required><label>To</label><input name="destination" required><label>Travel date</label><input type="date" name="travel_date" min="<?php echo date('Y-m-d'); ?>" required><label>Departure time</label><input type="time" name="departure_time" required><label>Total seats</label><input type="number" name="total_seats" min="1" max="100" value="40" required><label>Fare per seat (₹)</label><input type="number" name="price" min="1" step="0.01" required><button name="add_bus">Add Bus</button></form></div><h3>Bus Schedule</h3><table><tr><th>Bus</th><th>Category</th><th>Route</th><th>Date</th><th>Time</th><th>Seats</th><th>Fare</th></tr><?php while($b=mysqli_fetch_assoc($buses)){?><tr><td><?php echo htmlspecialchars($b['bus_name']);?></td><td><?php echo htmlspecialchars($b['category']);?></td><td><?php echo htmlspecialchars($b['source'].' → '.$b['destination']);?></td><td><?php echo $b['travel_date'];?></td><td><?php echo $b['departure_time'];?></td><td><?php echo $b['total_seats'];?></td><td>₹<?php echo $b['price'];?></td></tr><?php }?></table><h3>Booking Report</h3><table><tr><th>ID</th><th>User</th><th>Bus</th><th>Route</th><th>Passenger</th><th>Seat</th><th>Fare</th><th>Status</th><th>Action</th></tr><?php while($b=mysqli_fetch_assoc($bookings)){?><tr><td><?php echo $b['id'];?></td><td><?php echo htmlspecialchars($b['name']);?></td><td><?php echo htmlspecialchars($b['bus_name']);?></td><td><?php echo htmlspecialchars($b['source'].' → '.$b['destination']);?></td><td><?php echo htmlspecialchars($b['passenger_name']);?></td><td><?php echo htmlspecialchars($b['seat_no']);?></td><td>₹<?php echo $b['total_price'];?></td><td><?php echo htmlspecialchars($b['status']);?></td><td><?php if($b['status']==='Booked')echo '<form method="post"><input type="hidden" name="booking_id" value="'.$b['id'].'"><button name="cancel_booking">Cancel</button></form>';?></td></tr><?php }?></table></div></body></html>